import { tokenCache } from '@clerk/expo/token-cache';
import { Slot, usePathname, useRouter } from 'expo-router';
import { useEffect } from 'react';
import { StatusBar } from 'expo-status-bar';
import { SafeAreaProvider } from 'react-native-safe-area-context';
import { useAuth } from '@clerk/expo';
import { setTokenSource } from '../src/lib/clerkToken';
import { upsertProfile } from '../src/api/profile';
import { colors } from '../src/theme';

const publishableKey = process.env.EXPO_PUBLIC_CLERK_PUBLISHABLE_KEY;

/**
 * Registers Clerk's token getter into the Supabase client and upserts the
 * application profile once a real session exists. Idempotent.
 */
function AuthBridge() {
  const { isSignedIn, getToken, userId, isLoaded } = useAuth();

  useEffect(() => {
    setTokenSource(() => getToken());
  }, [getToken]);

  useEffect(() => {
    if (!isLoaded || !isSignedIn || !userId) return;
    const { sessionId, sessionToken, sessionClaims } = {} as any;
    void sessionId; void sessionToken; void sessionClaims;
    (async () => {
      let name: string | undefined;
      let email: string | undefined;
      try {
        // Fetch fresh claims so profile fields are real Clerk data.
        const token = await getToken();
        if (token) {
          const [, payload] = token.split('.');
          const claims = JSON.parse(atob(payload.padEnd(Math.ceil(payload.length / 4) * 4, '=')));
          name = claims.name || claims.given_name || claims.username;
          email = claims.email || (claims.emails ?? []).find?.((e: any) => e.email_address === claims.primary_email_identifier)?.email_address;
        }
      } catch {
        // Fall back to URL-less upsert below with just the id.
      }
      await upsertProfile({ userId, name, email });
    })();
  }, [isLoaded, isSignedIn, userId]);

  return null;
}

export default function RootLayout() {
  return (
    <ClerkProvider publishableKey={publishableKey} tokenCache={tokenCache}>
      <SafeAreaProvider>
        <StatusBar style="light" />
        <AuthBridge />
        <Slot />
      </SafeAreaProvider>
    </ClerkProvider>
  );
}
